"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["8752"],{28822(e){e.exports=JSON.parse('{"id":"FIN-620","slug":"return-on-assets","term":"Return on Assets (ROA)","also_known_as":["ROA"],"difficulty":"Intermediate","definition":"Return on assets (ROA) is net income divided by total assets, showing how much profit a company generates from everything it owns.","explanation":["ROA measures how efficiently a company uses its assets, such as cash, inventory, equipment and buildings, to produce profit. It answers the question: for every unit of assets, how much profit does the business earn?","For example, a company with net income of 150,000 and total assets of 1.5 million has an ROA of 10%. Analysts often use average total assets over the year rather than the year-end figure, to account for changes during the period.","ROA varies widely by industry. Asset-light businesses, such as software or consulting firms, tend to have high ROA because they need few physical assets. Asset-heavy businesses, such as utilities, manufacturers and banks, tend to have lower ROA. For banks, an ROA of around 1% can be considered healthy, because they hold very large amounts of assets relative to their profits.","ROA is less affected by debt than return on equity, because it uses total assets regardless of how they are financed. However, because net income is after interest, more borrowing can still affect it. Some analysts adjust the numerator to add back after-tax interest for a cleaner comparison."],"note":"","total":1725,"prev":{"slug":"return","term":"Return"},"next":{"slug":"return-on-capital-employed","term":"Return on Capital Employed (ROCE)"}}')}}]);